import { motion } from "framer-motion";

const programs = [
  {
    title: "Weight Training",
    desc: "Structured strength training focused on form, progression, and consistency.",
    img: "https://images.unsplash.com/photo-1517836357463-d25dfeac3438",
  },
  {
    title: "Cardio Fitness",
    desc: "Planned cardio workouts designed to build endurance and stamina.",
    img: "https://images.unsplash.com/photo-1549576490-b0b4831ef60a",
  },
  {
    title: "Personal Training",
    desc: "One-on-one coaching tailored to individual fitness goals.",
    img: "https://images.unsplash.com/photo-1599058917212-d750089bc07e",
  },
  {
    title: "Zumba",
    desc: "Dance-based cardio sessions focused on rhythm and endurance.",
    img: "https://images.unsplash.com/photo-1544367567-0f2fcb009e0b",
  },
  {
    title: "Group Training",
    desc: "Coach-led group workouts designed for motivation and consistency.",
    img: "https://images.unsplash.com/photo-1593079831268-3381b0db4a77",
  },
];

export default function Programs() {
  return (
    <section
      id="programs"
      className="bg-black text-white py-32 px-6"
    >
      <div className="max-w-7xl mx-auto">

        {/* Heading */}
        <div className="text-center max-w-3xl mx-auto mb-20">
          <h2 className="text-4xl md:text-5xl font-bold">
            Our <span className="text-red-600">Programs</span>
          </h2>
          <p className="mt-6 text-gray-400">
            Structured programs designed to support every fitness goal.
          </p>
        </div>

        {/* Grid */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {programs.map((item, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: i * 0.1 }}
              className="rounded-2xl overflow-hidden border border-white/10 bg-black/40 backdrop-blur shadow-xl flex flex-col"
            >
              {/* Image */}
              <div className="h-52 overflow-hidden">
                <img
                  src={`${item.img}?auto=format&fit=crop&w=900&q=80`}
                  alt={item.title}
                  className="w-full h-full object-cover hover:scale-105 transition duration-500"
                />
              </div>

              {/* Content */}
              <div className="p-6 flex flex-col flex-1">
                <h3 className="text-xl font-semibold">{item.title}</h3>
                <p className="text-gray-400 text-sm mt-3 flex-1">
                  {item.desc}
                </p>

                <button className="mt-6 w-fit px-6 py-2 rounded-full border border-red-600 text-red-500 hover:bg-red-600 hover:text-white transition">
                  View Details
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Footer Note */}
        <p className="mt-20 text-center text-sm text-gray-500 max-w-3xl mx-auto">
          Program availability is based on services offered at each branch.
          Only programs listed for a branch are available at that location.
        </p>

      </div>
    </section>
  );
}
